    <section class="erp-panel erp-data-panel erp-detail-section"><header class="erp-panel-head"><div><h2>Auditoria</h2><p>Criação do título e parcelas em uma transação.</p></div></header><?php if($auditEvents===[]): ?><div class="erp-empty-state"><strong>Evento de auditoria não encontrado.</strong></div><?php else: ?><div class="erp-table-wrap"><table><thead><tr><th>Evento</th><th>Ator</th><th>Data</th><th>Detalhes</th></tr></thead><tbody><?php foreach($auditEvents as $event): ?><tr><td><?= $this->e((string)$event['event_type']) ?></td><td><?= $this->e((string)($event['actor_name']?:'Usuário #'.(int)$event['actor_user_id'])) ?></td><td><?= $this->e((string)$event['created_at']) ?></td><td><?= $this->e((string)($event['metadata']??'')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
